    "welcome.dateHint": { en: "This is for dates you type. Dates on screen always show the month as a word (3 Apr 2026).", es: "Esto es para las fechas que escribes. En pantalla, las fechas siempre muestran el mes con letras (3 abr 2026)." },
    "welcome.curLabel": { en: "Your currencies", es: "Tus monedas" },
    "welcome.curHint": { en: "Tap the currencies you use. Double-tap one to make it your main currency (★): totals, budgets and reports are shown in it. You can change it any time in More → Main currency, and switching back restores everything exactly.", es: "Toca las monedas que usas. Toca dos veces una para hacerla tu moneda principal (★): los totales, presupuestos y reportes se muestran en ella. Puedes cambiarla cuando quieras en Más → Moneda principal, y volver atrás lo deja todo exactamente igual." },
    "welcome.mainLabel": { en: "Main currency: ★ {code}", es: "Moneda principal: ★ {code}" },
