    "tour.done": { en: "Start using the app", es: "Empezar a usar la app" },
    "tour.overview.title": { en: "See where your money goes", es: "Mira a dónde va tu dinero" },
    "tour.overview.body": { en: "The Overview tab adds up each month: income, expenses, investments and what’s left (Net). Below, it splits it by category. Tap a category to see the entries behind it.", es: "La pestaña Resumen suma cada mes: ingresos, gastos, inversiones y lo que queda (Neto). Más abajo lo reparte por categoría. Toca una categoría para ver los movimientos que la forman." },
    "tour.budgets.title": { en: "Set a budget", es: "Fija un presupuesto" },
    "tour.bank.title": { en: "Bank transactions arrive by themselves", es: "Los movimientos del banco llegan solos" },
    "tour.bank.body": { en: "When your bank emails you about a payment, it appears under “Needs review” on the Entries tab. Check it and confirm. Nothing counts until you do.", es: "Cuando tu banco te envía un correo por un pago, aparece en “Por revisar” en la pestaña Movimientos. Revísalo y confírmalo. Nada cuenta hasta que lo hagas." },
    "tour.more.title": { en: "Everything else is under More", es: "Todo lo demás está en Más" },
    "tour.more.body": { en: "Accounts, cards & platforms, exchange rates, exporting your data and your language are under More. You can open this tour again there, under “How to use the app”.", es: "Cuentas, tarjetas y plataformas, tipos de cambio, exportar tus datos y tu idioma están en Más. Puedes abrir este recorrido de nuevo ahí, en “Cómo usar la app”." },
    "tour.more.extras": { en: " “Extra features” turns on the extras you skipped.", es: " “Funciones extra” activa los extras que omitiste." },
    "more.mainCurrency": { en: "💱 Main currency", es: "💱 Moneda principal" },
    "mainCur.title": { en: "Main currency", es: "Moneda principal" },
    "mainCur.current": { en: "Your main currency: ★ {code}", es: "Tu moneda principal: ★ {code}" },
    "mainCur.reversible": { en: "You can change this at any time, and switching back restores exactly what you had. Nothing in your data is rewritten: your entries keep their own currencies, and only the totals are shown in the main currency.", es: "Puedes cambiarla cuando quieras, y volver atrás deja todo exactamente como estaba. No se reescribe nada de tus datos: tus movimientos conservan su propia moneda y solo los totales se muestran en la moneda principal." },
    "mainCur.change": { en: "Change main currency…", es: "Cambiar moneda principal…" },
    "mainCur.confirm": { en: "Switch your main currency from {from} to {to}? Totals, budgets and reports will be shown in {to}. You can switch back at any time.", es: "¿Cambiar tu moneda principal de {from} a {to}? Los totales, presupuestos y reportes se mostrarán en {to}. Puedes volver atrás cuando quieras." },
    "mainCur.rateQuestion": { en: "How many {to} is 1 {from} worth today?", es: "¿Cuántos {to} vale hoy 1 {from}?" },
    "mainCur.estimate": { en: "Months before {month} use that first {to} rate as an estimate. You can refine them under More → Exchange rates, and everything updates by itself.", es: "Los meses anteriores a {month} usan ese primer tipo de cambio de {to} como estimado. Puedes afinarlos en Más → Tipos de cambio y todo se actualiza solo." },
    "mainCur.same": { en: "That is already your main currency.", es: "Esa ya es tu moneda principal." },
    "mainCur.rateNeeded": { en: "Enter a rate greater than zero.", es: "Ingresa un tipo de cambio mayor que cero." },
    "mainCur.apply": { en: "Switch main currency", es: "Cambiar moneda principal" },
    "mainCur.switching": { en: "Switching…", es: "Cambiando…" },
