    "wa.last4": { en: "Last 4 digits (optional)", es: "Últimos 4 dígitos (opcional)" },
    "wa.last4Hint": { en: "They help the app recognise your bank e-mails. Never the full number.", es: "Ayudan a la app a reconocer los correos de tu banco. Nunca el número completo." },
